package br.com.archlab.simulation.core.v3;
import java.util.*;import static br.com.archlab.simulation.core.v3.RuntimeEntityV3.*;import static br.com.archlab.simulation.core.v3.SimulationMetricsV3.*;
/** Observed intervals are integrated once; inclusive waiting is work, not additive latency. */
public final class ResultProjectorV3 {
    public record Projection(SimulationEngineV3.Checkpoint checkpoint,InterpreterStateV3 control,PublicSnapshotV3 initialState,PublicSnapshotV3 finalState,List<StateDeltaV3> deltas,List<TimelineActivityV3> timeline,SimulationMetricsV3 metrics){public Projection{deltas=List.copyOf(deltas);timeline=List.copyOf(timeline);}}
    private record Point(long time,RuntimeEntityV3 entity,IdentifierV3 source){}
    private static final class History {final List<Point> points=new ArrayList<>();Point first(){return points.getFirst();}Point last(){return points.getLast();}Point terminal(){return points.stream().filter(p->p.entity().stateName()!=null && StateTransitionsV3.terminal(p.entity().kind(),p.entity().stateName())).findFirst().orElse(null);}}
    private final SimulationEngineV3.Checkpoint checkpoint;private final RuntimeStateV3 state;private final InterpreterStateV3 control;private final long observed;
    private final Map<IdentifierV3,History> history=new LinkedHashMap<>();private final Map<IdentifierV3,SimulationEventV3> createdBy=new HashMap<>();private final Map<IdentifierV3,Long> processingByActivation=new HashMap<>(),transportByInteraction=new HashMap<>();
    private ResultProjectorV3(SimulationEngineV3.Checkpoint checkpoint){this.checkpoint=checkpoint;state=checkpoint.current().state();control=state.entities().values().stream().filter(e->e instanceof Control).map(e->((Control)e).data()).findFirst().orElseThrow();observed=checkpoint.current().agenda().nowMs();
        for(var entity:checkpoint.initial().state().entities().values())if(entity.kind()!=Kind.CONTROL)append(entity,0,null);
        for(var commit:checkpoint.current().journal())for(var delta:commit.deltas()){var entity=delta.after()==null?delta.before():delta.after();if(entity.kind()==Kind.CONTROL)continue;if(delta.before()==null)createdBy.put(entity.id(),commit.event().payload());if(delta.after()!=null)append(delta.after(),delta.timestampMs(),delta.sourceTraceRecordId());}
        for(var entry:control.runs().entrySet()){var run=entry.getValue();var status=state.entities().get(entry.getKey());if(!process(run))continue;long duration=0;var h=history.get(entry.getKey());if(h==null)continue;var terminal=h.terminal();if(terminal!=null && !status.stateName().equals("READY"))duration=Math.max(0,terminal.time()-run.startedAt());else if(status.stateName().equals("RUNNING"))duration=Math.max(0,observed-run.startedAt());
            if(run.claim()!=null && state.entities().get(run.claim()) instanceof WaitClaim claim && claim.status()!=WaitClaimStatus.ACQUIRED)duration=0;processingByActivation.merge(run.activation(),duration,Math::addExact);}
        for(var trace:checkpoint.current().trace())if(trace.detail() instanceof TraceRecordV3.Message message && message.attemptId()!=null){var data=control.attemptCalls().get(message.attemptId());if(data!=null && (trace.kind()==TraceRecordV3.Kind.MESSAGE_ARRIVED || trace.kind()==TraceRecordV3.Kind.RESPONSE_ARRIVED || trace.kind()==TraceRecordV3.Kind.RESPONSE_ARRIVED_LATE))transportByInteraction.merge(((Attempt)state.entities().get(message.attemptId())).interactionId(),data.latency(),Math::addExact);}
        for(var commit:checkpoint.current().journal())if(commit.event().payload() instanceof SimulationEventV3.ConsumerAckArrivalDue ack && commit.decision() instanceof DispatchDecisionV3.Apply){var data=control.attemptCalls().values().stream().filter(c->ack.deliveryAttemptId().equals(c.deliveryAttempt())).findFirst().orElse(null);if(data!=null){var queue=control.deliveries().get(data.consumerEntry()).queue();transportByInteraction.merge(((Attempt)state.entities().get(data.attempt())).interactionId(),number(resource(queue).properties(),"ackDelayMs",0),Math::addExact);}}
    }
    public static Projection project(SimulationEngineV3.Checkpoint checkpoint){var projector=new ResultProjectorV3(checkpoint);var initial=PublicSnapshotV3.from(checkpoint.initial().state(),checkpoint.initial().agenda().nowMs());var end=PublicSnapshotV3.from(checkpoint.current().state(),checkpoint.current().agenda().nowMs());var deltas=checkpoint.current().journal().stream().flatMap(c->c.deltas().stream()).flatMap(d->d.publicProjection().stream()).toList();
        var replay=PublicReplayV3.replay(initial,deltas,checkpoint.current().trace(),end.virtualTimeMs());if(!replay.equals(end))throw new IllegalStateException("Public replay does not equal final state");return new Projection(checkpoint,projector.control,initial,end,deltas,projector.timeline(),projector.metrics());}
    private void append(RuntimeEntityV3 entity,long time,IdentifierV3 source){history.computeIfAbsent(entity.id(),x->new History()).points.add(new Point(time,entity,source));}
    private long span(History h,String state){long sum=0;for(int i=0;i<h.points.size();i++){var point=h.points.get(i);long until=i+1<h.points.size()?h.points.get(i+1).time():observed;if(Objects.equals(point.entity().stateName(),state))sum=Math.addExact(sum,until-point.time());}return sum;}
    private Long terminal(IdentifierV3 id){var h=history.get(id);return h==null || h.terminal()==null?null:h.terminal().time();}
    private long elapsed(IdentifierV3 id){var h=history.get(id);return (h.terminal()==null?observed:h.terminal().time())-h.first().time();}
    private ArchitectureV3.Operation operation(IdentifierV3 id){return checkpoint.request().architecture().operations().stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}
    private ArchitectureV3.Resource resource(IdentifierV3 id){return checkpoint.request().architecture().resources().stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}
    private ExecutionPlanV3.Step definition(InterpreterStateV3.Run run){var operation=control.activations().get(run.activation()).operationId();return checkpoint.request().architecture().executionPlans().stream().filter(x->x.operationId().equals(operation)).flatMap(x->x.steps().stream()).filter(x->x.id().equals(run.step())).findFirst().orElse(null);}
    private boolean process(InterpreterStateV3.Run run){var step=definition(run);return step instanceof ExecutionPlanV3.Process || step==null && run.step().value().equals("process");}
    private IdentifierV3 source(IdentifierV3 interaction){var call=control.calls().get(interaction);if(call!=null){if(call.callerActivation()!=null)return ((Activation)state.entities().get(call.callerActivation())).componentId();if(call.consumerEntry()!=null)return resource(control.deliveries().get(call.consumerEntry()).queue()).ownerId();return checkpoint.request().scenario().entry().componentId();}var publication=control.publications().values().stream().filter(p->interaction.equals(p.interaction())).findFirst().orElseThrow();return ((Activation)state.entities().get(publication.activation())).componentId();}
    private IdentifierV3 target(IdentifierV3 interaction){var call=control.calls().get(interaction);if(call!=null)return operation(call.targetOperation()).ownerId();return resource(control.publications().values().stream().filter(p->interaction.equals(p.interaction())).findFirst().orElseThrow().resource()).ownerId();}
    private SimulationMetricsV3 metrics(){var components=new ArrayList<ComponentMetric>();var interactions=new ArrayList<InteractionMetric>();var resources=new ArrayList<ResourceMetric>();var groups=new ArrayList<GroupMetric>();
        for(var entity:state.entities().values())if(entity instanceof Interaction interaction){var h=history.get(entity.id());long remote=0;for(var attempt:interaction.attemptIds()){var call=control.attemptCalls().get(attempt);if(call!=null)remote=Math.addExact(remote,processingByActivation.getOrDefault(call.callee(),0L));}var current=control.calls().get(interaction.id());long waiting=current==null || current.awaitResponse() || current.consumerEntry()!=null?elapsed(interaction.id()):0;Long end=terminal(interaction.id());interactions.add(new InteractionMetric(interaction.id(),source(interaction.id()),target(interaction.id()),h.first().time(),end,end==null?null:end-h.first().time(),interaction.attemptIds().size(),transportByInteraction.getOrDefault(interaction.id(),0L),remote,waiting));}
        for(var component:checkpoint.request().architecture().components()){long count=0,completed=0,failed=0,processing=0,waiting=0,communication=0;
            for(var entity:state.entities().values())if(entity instanceof Activation activation && activation.componentId().equals(component.id())){count++;if(activation.status()==ActivationStatus.COMPLETED)completed++;if(activation.status()==ActivationStatus.FAILED || activation.status()==ActivationStatus.CANCELLED)failed++;processing=Math.addExact(processing,processingByActivation.getOrDefault(activation.id(),0L));waiting=Math.addExact(waiting,span(history.get(activation.id()),"WAITING"));}
            for(var interaction:interactions)if(interaction.sourceComponentId().equals(component.id())){communication=Math.addExact(communication,interaction.transportWorkMs());var call=control.calls().get(interaction.interactionId());if(call!=null && call.root())waiting=Math.addExact(waiting,interaction.waitingWorkMs());}
            for(var entry:control.publications().entrySet())if(resource(entry.getValue().resource()).ownerId().equals(component.id())){var h=history.get(entry.getKey());long duration=number(component.properties(),"processingMs",0);processing=Math.addExact(processing,Math.min(duration,(h.terminal()==null?observed:h.terminal().time())-h.first().time()));}
            components.add(new ComponentMetric(component.id(),count,completed,failed,processing,waiting,communication));}
        for(var r:checkpoint.request().architecture().resources()){long acquired=0,rejected=0,timeouts=0,waiting=0,busy=0,max=0;
            for(var entity:state.entities().values())if(entity instanceof WaitClaim claim && claim.resourceId().equals(r.id())){if(claim.status()==WaitClaimStatus.ACQUIRED)acquired++;if(claim.status()==WaitClaimStatus.REJECTED)rejected++;if(claim.status()==WaitClaimStatus.TIMED_OUT)timeouts++;waiting=Math.addExact(waiting,span(history.get(claim.id()),"WAITING"));}
            var h=history.get(r.id());if(r.typeId().value().equals("MESSAGE_QUEUE")){long inUse=0;for(var commit:checkpoint.current().journal())for(var d:commit.deltas()){if(d.after() instanceof QueueEntry entry && entry.queueId().equals(r.id())){boolean before=d.before()!=null && !StateTransitionsV3.terminal(d.before().kind(),d.before().stateName());boolean after=!StateTransitionsV3.terminal(entry.kind(),entry.stateName());inUse+=(after?1:0)-(before?1:0);max=Math.max(max,inUse);}}
                for(var entity:state.entities().values())if(entity instanceof QueueEntry entry && entry.queueId().equals(r.id()))busy=Math.addExact(busy,elapsed(entry.id()));
            }else if(h!=null)for(int i=0;i<h.points.size();i++){var point=h.points.get(i);var value=(Resource)point.entity();long used=value.inUse()==null?0:value.inUse();long end=i+1<h.points.size()?h.points.get(i+1).time():observed;busy=Math.addExact(busy,Math.multiplyExact(used,end-point.time()));max=Math.max(max,used);}
            resources.add(new ResourceMetric(r.id(),acquired,rejected,timeouts,waiting,busy,max));}
        for(var entity:state.entities().values())if(entity instanceof ParallelGroup group){var h=history.get(group.id());Long joined=h.points.stream().filter(p->p.entity().stateName().equals("JOIN_SATISFIED")).map(Point::time).findFirst().orElse(null);groups.add(new GroupMetric(group.id(),h.first().time(),joined,terminal(group.id())));}
        var critical=new ArrayList<CriticalPath>();for(var target:List.of("PRINCIPAL_RESPONSE","PRINCIPAL_TERMINAL","GLOBAL_COMPLETION"))critical.add(new CriticalPath(target,null,List.of(),"unavailable-v1","CAUSAL_CRITICAL_PATH_NOT_COMPUTED"));
        boolean complete="COMPLETED".equals(control.globalStop());return new SimulationMetricsV3(control.principalResponseAt(),control.principalTerminalAt(),complete?observed:null,observed,control.principalResponseAt()==null?null:Math.max(0,observed-control.principalResponseAt()),components,interactions,resources,groups,critical);
    }
    private List<TimelineActivityV3> timeline(){var result=new ArrayList<TimelineActivityV3>();IdentifierV3 first=checkpoint.current().trace().isEmpty()?null:checkpoint.current().trace().getFirst().recordId();if(first==null)return List.of();var principal=state.entities().values().stream().filter(x->x instanceof Principal).findFirst().orElseThrow();var principalHistory=history.get(principal.id());result.add(new TimelineActivityV3(activity(principal.id()),null,checkpoint.request().scenario().entry().componentId(),null,"ROOT_OPERATION",0,control.principalTerminalAt(),principal.stateName(),first,principalHistory.terminal()==null?null:principalHistory.terminal().source()));
        for(var entity:state.entities().values()){if(!Set.of(Kind.ACTIVATION,Kind.INTERACTION,Kind.STEP_EXECUTION,Kind.PARALLEL_GROUP,Kind.QUEUE_ENTRY,Kind.PUBLICATION,Kind.DELIVERY_ATTEMPT).contains(entity.kind()))continue;var h=history.get(entity.id());IdentifierV3 parent=null,component=null,activation=null;String kind=entity.kind().name();
            if(entity instanceof Activation a){activation=a.id();component=a.componentId();var data=control.activations().get(a.id());parent=data.returnInteraction()!=null?activity(data.returnInteraction()):data.returnGroup()!=null?activity(control.groups().get(data.returnGroup()).forkRun()):null;}
            else if(entity instanceof StepExecution){var run=control.runs().get(entity.id());if(run==null)continue;activation=run.activation();component=((Activation)state.entities().get(activation)).componentId();parent=activity(activation);var definition=definition(run);kind=definition==null?(process(run)?"PROCESS":"COMPLETE"):definition.getClass().getSimpleName().toUpperCase(Locale.ROOT);}
            else if(entity instanceof Interaction i){component=source(i.id());var call=control.calls().get(i.id());if(call!=null && call.consumerEntry()!=null)parent=activity(call.consumerEntry());else if(createdBy.get(i.id()) instanceof SimulationEventV3.StepStartDue step)parent=activity(step.stepExecutionId());else if(call!=null && call.root())parent=activity(principal.id());}
            else if(entity instanceof ParallelGroup g){var data=control.groups().get(g.id());parent=activity(data.forkRun());activation=data.activation();component=((Activation)state.entities().get(activation)).componentId();}
            else if(entity instanceof QueueEntry q){var data=control.deliveries().get(q.id());component=resource(q.queueId()).ownerId();parent=data!=null && data.publication()!=null?activity(data.publication()):null;}
            else if(entity instanceof Publication pub){var data=control.publications().get(pub.id());component=resource(data.resource()).ownerId();parent=activity(data.run());}
            else if(entity instanceof DeliveryAttempt delivery){parent=activity(delivery.queueEntryId());component=resource(((QueueEntry)state.entities().get(delivery.queueEntryId())).queueId()).ownerId();}
            result.add(new TimelineActivityV3(activity(entity.id()),parent,component,activation,kind,h.first().time(),h.terminal()==null?null:h.terminal().time(),entity.stateName(),h.first().source()==null?first:h.first().source(),h.terminal()==null?null:h.terminal().source()));
        }
        var ids=new HashSet<IdentifierV3>();result.forEach(a->ids.add(a.activityId()));for(var a:result)if(a.parentActivityId()!=null && !ids.contains(a.parentActivityId()))throw new IllegalStateException("Missing timeline parent");result.sort(Comparator.comparingLong(TimelineActivityV3::startedAtMs).thenComparing(a->a.activityId().value()));return List.copyOf(result);
    }
    private static IdentifierV3 activity(IdentifierV3 id){return new IdentifierV3(id.value()+"-activity");}
    private static long number(Map<String,PropertyValueV3> values,String key,long fallback){return values.get(key) instanceof PropertyValueV3.IntegerValue n?n.value():fallback;}
}
